/**
 * 根据 src/model-catalog.ts 生成 README 里的模型表格。
 *
 * 用法：npm run models:readme
 * （先编译，再改写 README.md 中 models:start / models:end 两个标记之间的内容）。
 * 测试会检查 README 是否与清单一致，忘了同步时 npm test 会提示运行本命令。
 */
const fs = require('node:fs');
const path = require('node:path');

const README_PATH = path.join(__dirname, '..', 'README.md');
const START_MARKER =
  '<!-- models:start — generated by `npm run models:readme`; edit src/model-catalog.ts instead -->';
const END_MARKER = '<!-- models:end -->';

/** 1000000 → 1M，204800 → 205K。 */
function formatTokens(count) {
  return count >= 1_000_000
    ? `${Number((count / 1_000_000).toFixed(1))}M`
    : `${Math.round(count / 1000)}K`;
}

/** 把编译后的模型定义渲染成 Markdown 表格（不含标记）。 */
function renderModelTable() {
  const {
    GLM_MODEL_DEFINITIONS,
    describeThinkingSupport,
  } = require('../out/models.js');
  const yesNo = value => (value ? 'Yes' : 'No');
  const rows = GLM_MODEL_DEFINITIONS.map(model =>
    [
      model.name,
      `\`${model.id}\``,
      formatTokens(model.maxInputTokens),
      formatTokens(model.maxOutputTokens),
      describeThinkingSupport(model.thinkingSupport),
      yesNo(model.capabilities.imageInput),
      yesNo(model.capabilities.toolCalling),
    ].join(' | '),
  );
  return [
    '| Model | API ID | Context | Output | Thinking | Image Input | Tool Calling |',
    '|---|---|---|---|---|---|---|',
    ...rows.map(row => `| ${row} |`),
  ].join('\n');
}

/** 返回 README 中两个标记之间的现有内容；缺少标记时抛错。 */
function readModelSection(readme) {
  const start = readme.indexOf(START_MARKER);
  const end = readme.indexOf(END_MARKER);
  if (start === -1 || end === -1 || end < start) {
    throw new Error(
      `README.md must contain the markers:\n${START_MARKER}\n${END_MARKER}`,
    );
  }
  return {
    start: start + START_MARKER.length,
    end,
    content: readme.slice(start + START_MARKER.length, end).trim(),
  };
}

function syncReadme() {
  const readme = fs.readFileSync(README_PATH, 'utf8');
  const section = readModelSection(readme);
  const next =
    readme.slice(0, section.start) +
    `\n\n${renderModelTable()}\n\n` +
    readme.slice(section.end);
  if (next === readme) {
    console.log('README model table is already up to date.');
    return;
  }
  fs.writeFileSync(README_PATH, next);
  console.log('README model table updated.');
}

module.exports = {README_PATH, readModelSection, renderModelTable};

if (require.main === module) {
  syncReadme();
}
